package io.archly.ai;
import java.time.Instant;import java.util.UUID;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
interface AiUsageRepository extends JpaRepository<AiUsageEvent,UUID>{@Query("select coalesce(sum(u.estimatedCostMicros),0) from AiUsageEvent u where u.occurredAt>=:since")long costSince(@Param("since")Instant since);@Query("select coalesce(sum(u.estimatedCostMicros),0) from AiUsageEvent u where u.userSubject=:user and u.occurredAt>=:since")long userCostSince(@Param("user")String user,@Param("since")Instant since);@Query("select coalesce(sum(u.inputTokens),0),coalesce(sum(u.outputTokens),0),count(u),coalesce(sum(case when u.status<>'SUCCESS' then 1 else 0 end),0) from AiUsageEvent u where u.occurredAt>=:since")Object[] totalsSince(@Param("since")Instant since);boolean existsByRequestId(String requestId);long deleteByOccurredAtBefore(Instant cutoff);}
